   344→
   345→// Type represents a type
   346→type Type struct {
   347→	Name       string
   348→	IsOption   bool
   349→	IsResult   bool
   350→	ErrorType  *Type
   351→	ElementType *Type
   352→	IsArray    bool
   353→	IsPrimitive bool
   354→	IsFunction bool
   355→	ParamTypes []Type
   356→	ReturnType *Type
   357→}
   358→
   359→// String returns string representation of type
   360→func (t *Type) String() string {
   361→	if t == nil {
   362→		return "unknown"
   363→	}
   364→
   365→	if t.IsOption {
   366→		return "?" + t.ElementType.String()
   367→	}
   368→	if t.IsResult {
   369→		errStr := "String"
   370→		if t.ErrorType != nil {
   371→			errStr = t.ErrorType.String()
   372→		}
   373→		return "Result(" + t.ElementType.String() + ", " + errStr + ")"
   374→	}
   375→	if t.IsArray {
   376→		return "[]" + t.ElementType.String()
   377→	}
   378→	if t.IsFunction {
   379→		return "fn"
   380→	}
   381→	return t.Name
   382→}
   383→
