   567→// parseBlockStatement parses a block statement
   568→func (p *Parser) parseBlockStatement() (ast.Statement, error) {
   569→	var statements []ast.Statement
   570→
   571→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   572→		stmt, err := p.parseStatement()
   573→		if err != nil {
   574→			return nil, err
   575→		}
   576→		if stmt != nil {
   577→			statements = append(statements, stmt)
   578→		}
   579→	}
   580→
   581→	if !p.match(lexer.TknRBrace) {
   582→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   583→	}
   584→
   585→	return &ast.BlockStatement{Statements: statements}, nil
   586→}
