   588→// parseExpression parses an expression
   589→func (p *Parser) parseExpression() (ast.Expression, error) {
   590→	return p.parseBinaryExpression(0)
   591→}
   592→
   593→// parseBinaryExpression parses binary expressions with precedence
   594→func (p *Parser) parseBinaryExpression(minPrec int) (ast.Expression, error) {
   595→	left, err := p.parseUnary()
   596→	if err != nil {
   597→		return nil, err
   598→	}
   599→
   600→	for {
   601→		if p.isAtEnd() || !p.isOperator(p.current().Type) {
   602→			break
   603→		}
   604→
   605→		op := p.current()
   606→		prec := getPrecedence(op.Type)
   607→		if prec < minPrec {
   608→			break
   609→		}
   610→
   611→		p.advance()
   612→
   613→		right, err := p.parseBinaryExpression(prec + 1)
   614→		if err != nil {
   615→			return nil, err
   616→		}
   617→
   618→		left = &ast.BinaryExpression{
   619→			Left:     left,
   620→			Operator: op.Text,
   621→			Right:    right,
   622→		}
   623→	}
   624→
   625→	return left, nil
   626→}
   627→
   628→// parseUnary parses unary expressions
   629→func (p *Parser) parseUnary() (ast.Expression, error) {
   630→	if p.match(lexer.TknNot) {
   631→		operand, err := p.parseUnary()
   632→		if err != nil {
   633→			return nil, err
   634→		}
   635→		return &ast.UnaryExpression{
   636→			Operator: "!",
   637→			Operand:  operand,
   638→		}, nil
   639→	}
   640→
   641→	if p.match(lexer.TknMinus) {
   642→		operand, err := p.parseUnary()
   643→		if err != nil {
   644→			return nil, err
   645→		}
   646→		return &ast.UnaryExpression{
   647→			Operator: "-",
   648→			Operand:  operand,
   649→		}, nil
   650→	}
   651→
   652→	if p.match(lexer.TknAmpersand) {
   653→		operand, err := p.parseUnary()
   654→		if err != nil {
   655→			return nil, err
   656→		}
   657→		return &ast.UnaryExpression{
   658→			Operator: "&",
   659→			Operand:  operand,
   660→		}, nil
   661→	}
   662→
   663→	return p.parsePostfix()
   664→}
   665→
   666→// parsePostfix parses postfix expressions
   667→func (p *Parser) parsePostfix() (ast.Expression, error) {
   668→	expr, err := p.parsePrimary()
   669→	if err != nil {
   670→		return nil, err
   671→	}
   672→
   673→	for {
   674→		if p.match(lexer.TknLParen) {
   675→			// Function call
   676→			var args []ast.Expression
   677→			if !p.check(lexer.TknRParen) {
   678→				for {
   679→					arg, err := p.parseExpression()
   680→					if err != nil {
   681→						return nil, err
   682→					}
   683→					args = append(args, arg)
   684→
   685→					if !p.match(lexer.TknComma) {
   686→						break
   687→					}
   688→				}
   689→			}
   690→
   691→			if !p.match(lexer.TknRParen) {
   692→				return nil, fmt.Errorf("expected ')' at %d:%d", p.current().Line, p.current().Column)
   693→			}
   694→
   695→			expr = &ast.CallExpression{
   696→				Function:  expr,
   697→				Arguments: args,
   698→			}
   699→		} else if p.match(lexer.TknDot) {
   700→			// Field access or method call
   701→			fieldName := p.current().Text
   702→			if !p.match(lexer.TknIdentifier) {
   703→				return nil, fmt.Errorf("expected field name at %d:%d", p.current().Line, p.current().Column)
   704→			}
   705→
   706→			if p.match(lexer.TknLParen) {
   707→				// Method call
   708→				var args []ast.Expression
   709→				if !p.check(lexer.TknRParen) {
   710→					for {
   711→						arg, err := p.parseExpression()
   712→						if err != nil {
   713→							return nil, err
   714→						}
   715→						args = append(args, arg)
   716→
   717→						if !p.match(lexer.TknComma) {
   718→							break
   719→						}
   720→					}
   721→				}
   722→
   723→				if !p.match(lexer.TknRParen) {
   724→					return nil, fmt.Errorf("expected ')' at %d:%d", p.current().Line, p.current().Column)
   725→				}
   726→
   727→				expr = &ast.MethodCallExpression{
   728→					Object:    expr,
   729→					Method:    fieldName,
   730→					Arguments: args,
   731→				}
   732→			} else {
   733→				// Field access
   734→				expr = &ast.FieldExpression{
   735→					Object: expr,
   736→					Field:  fieldName,
   737→				}
   738→			}
   739→		} else if p.match(lexer.TknLBracket) {
   740→			// Index access
   741→			index, err := p.parseExpression()
   742→			if err != nil {
   743→				return nil, err
   744→			}
   745→
   746→			if !p.match(lexer.TknRBracket) {
   747→				return nil, fmt.Errorf("expected ']' at %d:%d", p.current().Line, p.current().Column)
   748→			}
   749→
   750→			expr = &ast.IndexExpression{
   751→				Object: expr,
   752→				Index:  index,
   753→			}
   754→		} else if p.match(lexer.TknQuestion) {
   755→			// Error propagation
   756→			expr = &ast.ErrorPropagation{Expression: expr}
   757→		} else {
   758→			break
   759→		}
   760→	}
   761→
   762→	return expr, nil
   763→}
   764→
   765→// parsePrimary parses primary expressions
   766→func (p *Parser) parsePrimary() (ast.Expression, error) {
   767→	// Literals
   768→	if p.match(lexer.TknInteger) {
   769→		val, err := strconv.ParseInt(p.previous().Text, 10, 64)
   770→		if err != nil {
   771→			return nil, fmt.Errorf("invalid integer: %s", p.previous().Text)
   772→		}
   773→		return &ast.IntegerLiteral{Value: val}, nil
   774→	}
   775→
   776→	if p.match(lexer.TknFloat) {
   777→		val, err := strconv.ParseFloat(p.previous().Text, 64)
   778→		if err != nil {
   779→			return nil, fmt.Errorf("invalid float: %s", p.previous().Text)
   780→		}
   781→		return &ast.FloatLiteral{Value: val}, nil
   782→	}
   783→
   784→	if p.match(lexer.TknString) {
   785→		return &ast.StringLiteral{Value: p.previous().Text}, nil
   786→	}
   787→
   788→	if p.match(lexer.TknTrue) {
   789→		return &ast.BoolLiteral{Value: true}, nil
   790→	}
   791→
   792→	if p.match(lexer.TknFalse) {
   793→		return &ast.BoolLiteral{Value: false}, nil
   794→	}
   795→
   796→	if p.match(lexer.TknNone) {
   797→		return &ast.NoneLiteral{}, nil
   798→	}
   799→
   800→	if p.match(lexer.TknIdentifier) {
   801→		return &ast.Identifier{Name: p.previous().Text}, nil
   802→	}
   803→
   804→	if p.match(lexer.TknLBracket) {
   805→		// Array literal
   806→		var elements []ast.Expression
   807→		if !p.check(lexer.TknRBracket) {
   808→			for {
   809→				elem, err := p.parseExpression()
   810→				if err != nil {
   811→					return nil, err
   812→				}
   813→				elements = append(elements, elem)
   814→
   815→				if !p.match(lexer.TknComma) {
   816→					break
   817→				}
   818→			}
   819→		}
   820→
   821→		if !p.match(lexer.TknRBracket) {
   822→			return nil, fmt.Errorf("expected ']' at %d:%d", p.current().Line, p.current().Column)
   823→		}
   824→
   825→		return &ast.ArrayExpression{Elements: elements}, nil
   826→	}
   827→
   828→	if p.match(lexer.TknIf) {
   829→		// Parse if expression
   830→		cond, err := p.parseExpression()
   831→		if err != nil {
   832→			return nil, err
   833→		}
   834→
   835→		if !p.match(lexer.TknLBrace) {
   836→			return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   837→		}
   838→
   839→		thenExpr, err := p.parseExpression()
   840→		if err != nil {
   841→			return nil, err
   842→		}
   843→
   844→		if !p.match(lexer.TknRBrace) {
   845→			return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   846→		}
   847→
   848→		var elseExpr ast.Expression
   849→		if p.match(lexer.TknElse) {
   850→			if p.match(lexer.TknLBrace) {
   851→				var err error
   852→				elseExpr, err = p.parseExpression()
   853→				if err != nil {
   854→					return nil, err
   855→				}
   856→
   857→				if !p.match(lexer.TknRBrace) {
   858→					return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   859→				}
   860→			}
   861→		}
   862→
   863→		return &ast.IfExpression{
   864→			Condition: cond,
   865→			ThenExpr:  thenExpr,
   866→			ElseExpr:  elseExpr,
   867→		}, nil
   868→	}
   869→
   870→	if p.match(lexer.TknLParen) {
   871→		expr, err := p.parseExpression()
   872→		if err != nil {
   873→			return nil, err
   874→		}
   875→
   876→		if !p.match(lexer.TknRParen) {
   877→			return nil, fmt.Errorf("expected ')' at %d:%d", p.current().Line, p.current().Column)
   878→		}
   879→
   880→		return expr, nil
   881→	}
   882→
   883→	return nil, fmt.Errorf("unexpected token: %v at %d:%d", p.current().Type, p.current().Line, p.current().Column)
   884→}
   885→
   886→// parsePattern parses a pattern
   887→func (p *Parser) parsePattern() (ast.Pattern, error) {
   888→	if p.match(lexer.TknIdentifier) {
   889→		return &ast.IdentifierPattern{Name: p.previous().Text}, nil
   890→	}
   891→
   892→	if p.match(lexer.TknInteger) {
   893→		val, _ := strconv.ParseInt(p.previous().Text, 10, 64)
   894→		return &ast.LiteralPattern{Value: &ast.IntegerLiteral{Value: val}}, nil
   895→	}
   896→
   897→	if p.match(lexer.TknString) {
   898→		return &ast.LiteralPattern{Value: &ast.StringLiteral{Value: p.previous().Text}}, nil
   899→	}
   900→
   901→	if p.match(lexer.TknTilde) {
   902→		return &ast.WildcardPattern{}, nil
   903→	}
   904→
   905→	return nil, fmt.Errorf("unexpected pattern at %d:%d", p.current().Line, p.current().Column)
   906→}
   907→
   908→// parseType parses a type
   909→func (p *Parser) parseType() *ast.Type {
   910→	// Handle option types (?)
   911→	isOption := p.match(lexer.TknQuestion)
   912→
   913→	// Get base type
   914→	var typeName string
   915→	if p.match(lexer.TknIdentifier) {
   916→		typeName = p.previous().Text
   917→	} else {
   918→		typeName = "unknown"
   919→	}
   920→
   921→	// Handle array types (prefix [])
   922→	isArray := false
   923→	if p.check(lexer.TknLBracket) {
   924→		p.advance()
   925→		if p.match(lexer.TknRBracket) {
   926→			isArray = true
   927→		} else {
   928→			p.pos-- // backtrack
   929→		}
   930→	}
   931→
   932→	return &ast.Type{
   933→		Name:       typeName,
   934→		IsOption:   isOption,
   935→		IsArray:    isArray,
   936→		IsPrimitive: isPrimitiveType(typeName),
   937→	}
   938→}
