     8→// Checker performs type checking on an AST
     9→type Checker struct {
    10→	GlobalScope *Scope
    11→	CurrentScope *Scope
    12→	Errors      []Error
    13→}
    14→
    15→// New creates a new type checker
    16→func New() *Checker {
    17→	globalScope := NewScope(nil)
    18→
    19→	// Add built-in types
    20→	globalScope.Define("i64", &PrimitiveType{Name: "i64"}, "type")
    21→	globalScope.Define("f64", &PrimitiveType{Name: "f64"}, "type")
    22→	globalScope.Define("string", &PrimitiveType{Name: "string"}, "type")
    23→	globalScope.Define("bool", &PrimitiveType{Name: "bool"}, "type")
    24→	globalScope.Define("none", &PrimitiveType{Name: "none"}, "type")
    25→
    26→	// Add built-in functions
    27→	// Note: println/print are variadic and accept any type
    28→	// For simplicity, we register them as accepting "any" and let codegen handle conversion
    29→	globalScope.Define("println", &BuiltinFunctionType{
    30→		Name: "println",
    31→		IsVariadic: true,
    32→	}, "function")
    33→	globalScope.Define("print", &BuiltinFunctionType{
    34→		Name: "print",
    35→		IsVariadic: true,
    36→	}, "function")
    37→	globalScope.Define("len", &BuiltinFunctionType{
    38→		Name: "len",
    39→		IsVariadic: false,
    40→	}, "function")
    41→
    42→	// Math stdlib functions
    43→	globalScope.Define("abs", &BuiltinFunctionType{
    44→		Name: "abs",
    45→		IsVariadic: false,
    46→	}, "function")
    47→	globalScope.Define("min", &BuiltinFunctionType{
    48→		Name: "min",
    49→		IsVariadic: false,
    50→	}, "function")
    51→	globalScope.Define("max", &BuiltinFunctionType{
    52→		Name: "max",
    53→		IsVariadic: false,
    54→	}, "function")
    55→
    56→	// Conversion functions (cast operations)
    57→	globalScope.Define("to_int", &BuiltinFunctionType{
    58→		Name: "to_int",
    59→		IsVariadic: true,
    60→	}, "function")
    61→	globalScope.Define("to_float", &BuiltinFunctionType{
    62→		Name: "to_float",
    63→		IsVariadic: true,
    64→	}, "function")
    65→
    66→	return &Checker{
    67→		GlobalScope: globalScope,
    68→		CurrentScope: globalScope,
    69→		Errors:      []Error{},
    70→	}
    71→}
