    73→// Check performs type checking on the program
    74→func (c *Checker) Check(program *ast.Program) ([]Error, error) {
    75→	// Check definitions first (function, type, struct)
    76→	for _, def := range program.Definitions {
    77→		c.checkDefinition(def)
    78→	}
    79→
    80→	// Check main body
    81→	for _, stmt := range program.MainBody {
    82→		c.checkStatement(stmt)
    83→	}
    84→
    85→	if len(c.Errors) > 0 {
    86→		return c.Errors, fmt.Errorf("type checking failed with %d errors", len(c.Errors))
    87→	}
    88→
    89→	return c.Errors, nil
    90→}
