    92→func (c *Checker) checkDefinition(def ast.Definition) {
    93→	switch d := def.(type) {
    94→	case *ast.FunctionDef:
    95→		c.checkFunctionDef(d)
    96→	case *ast.ExternDef:
    97→		c.checkExternDef(d)
    98→	case *ast.StructDef:
    99→		c.checkStructDef(d)
   100→	case *ast.TypeDef:
   101→		c.checkTypeDef(d)
   102→	case *ast.InterfaceDef:
   103→		c.checkInterfaceDef(d)
   104→	case *ast.EnumDef:
   105→		c.checkEnumDef(d)
   106→	}
   107→}
   108→
   109→func (c *Checker) checkFunctionDef(fn *ast.FunctionDef) {
   110→	// Create function scope
   111→	fnScope := NewScope(c.CurrentScope)
   112→	prevScope := c.CurrentScope
   113→	c.CurrentScope = fnScope
   114→
   115→	// Add parameters to scope
   116→	paramTypes := []Type{}
   117→	for _, param := range fn.Parameters {
   118→		paramType := c.astTypeToCheckerType(param.Type)
   119→		fnScope.Define(param.Name, paramType, "var")
   120→		paramTypes = append(paramTypes, paramType)
   121→	}
   122→
   123→	// Check return type
   124→	var returnType Type
   125→	if fn.ReturnType != nil {
   126→		returnType = c.astTypeToCheckerType(fn.ReturnType)
   127→	} else {
   128→		returnType = &PrimitiveType{Name: "none"}
   129→	}
   130→
   131→	// Check function body
   132→	for _, stmt := range fn.Body {
   133→		c.checkStatement(stmt)
   134→	}
   135→
   136→	// Register function in parent scope
   137→	fnType := &FunctionType{
   138→		ParamTypes: paramTypes,
   139→		ReturnType: returnType,
   140→	}
   141→	prevScope.Define(fn.Name, fnType, "function")
   142→
   143→	c.CurrentScope = prevScope
   144→}
   145→
   146→func (c *Checker) checkExternDef(ext *ast.ExternDef) {
   147→	// Register extern function in scope
   148→	paramTypes := []Type{}
   149→	for _, param := range ext.Parameters {
   150→		paramType := c.astTypeToCheckerType(param.Type)
   151→		paramTypes = append(paramTypes, paramType)
   152→	}
   153→
   154→	var returnType Type = &PrimitiveType{Name: "none"}
   155→	if ext.ReturnType != nil {
   156→		returnType = c.astTypeToCheckerType(ext.ReturnType)
   157→	}
   158→
   159→	fnType := &FunctionType{
   160→		ParamTypes: paramTypes,
   161→		ReturnType: returnType,
   162→	}
   163→	c.CurrentScope.Define(ext.Name, fnType, "extern_function")
   164→}
