   166→func (c *Checker) checkStructDef(str *ast.StructDef) {
   167→	fields := make(map[string]Type)
   168→	for _, field := range str.Fields {
   169→		fieldType := c.astTypeToCheckerType(field.Type)
   170→		fields[field.Name] = fieldType
   171→	}
   172→
   173→	structType := &StructType{
   174→		Name:   str.Name,
   175→		Fields: fields,
   176→	}
   177→
   178→	c.CurrentScope.Define(str.Name, structType, "type")
   179→}
