   193→func (c *Checker) checkStatement(stmt ast.Statement) {
   194→	switch s := stmt.(type) {
   195→	case *ast.LetStatement:
   196→		c.checkLetStatement(s)
   197→	case *ast.ConstStatement:
   198→		c.checkConstStatement(s)
   199→	case *ast.IfStatement:
   200→		c.checkIfStatement(s)
   201→	case *ast.ForStatement:
   202→		c.checkForStatement(s)
   203→	case *ast.ForRangeStatement:
   204→		c.checkForRangeStatement(s)
   205→	case *ast.ReturnStatement:
   206→		c.checkReturnStatement(s)
   207→	case *ast.MatchStatement:
   208→		c.checkMatchStatement(s)
   209→	case *ast.ExpressionStatement:
   210→		c.checkExpression(s.Expression)
   211→	case *ast.BlockStatement:
   212→		c.checkBlockStatement(s)
   213→	}
   214→}
