   216→func (c *Checker) checkLetStatement(let *ast.LetStatement) {
   217→	initType := c.checkExpression(let.Init)
   218→
   219→	var declaredType Type
   220→	if let.Type != nil {
   221→		declaredType = c.astTypeToCheckerType(let.Type)
   222→
   223→		// Verify init matches declared type
   224→		if !initType.Equal(declaredType) {
   225→			c.addError(0, 0, fmt.Sprintf(
   226→				"let %s: expected type %s, got %s",
   227→				let.Name, declaredType.TypeString(), initType.TypeString(),
   228→			))
   229→		}
   230→	} else {
   231→		declaredType = initType
   232→	}
   233→
   234→	c.CurrentScope.Define(let.Name, declaredType, "var")
   235→}
   236→
   237→func (c *Checker) checkConstStatement(const_ *ast.ConstStatement) {
   238→	initType := c.checkExpression(const_.Value)
   239→
   240→	var declaredType Type
   241→	if const_.Type != nil {
   242→		declaredType = c.astTypeToCheckerType(const_.Type)
   243→
   244→		if !initType.Equal(declaredType) {
   245→			c.addError(0, 0, fmt.Sprintf(
   246→				"const %s: expected type %s, got %s",
   247→				const_.Name, declaredType.TypeString(), initType.TypeString(),
   248→			))
   249→		}
   250→	} else {
   251→		declaredType = initType
   252→	}
   253→
   254→	c.CurrentScope.Define(const_.Name, declaredType, "const")
   255→}
