   257→func (c *Checker) checkIfStatement(ifStmt *ast.IfStatement) {
   258→	condType := c.checkExpression(ifStmt.Condition)
   259→
   260→	// Condition must be bool
   261→	if !condType.Equal(&PrimitiveType{Name: "bool"}) {
   262→		c.addError(0, 0, fmt.Sprintf(
   263→			"if condition: expected bool, got %s",
   264→			condType.TypeString(),
   265→		))
   266→	}
   267→
   268→	// Check then branch
   269→	for _, stmt := range ifStmt.ThenBody {
   270→		c.checkStatement(stmt)
   271→	}
   272→
   273→	// Check else branch (if any)
   274→	for _, stmt := range ifStmt.ElseBody {
   275→		c.checkStatement(stmt)
   276→	}
   277→}
