   279→func (c *Checker) checkForStatement(forStmt *ast.ForStatement) {
   280→	loopScope := NewScope(c.CurrentScope)
   281→	prevScope := c.CurrentScope
   282→	c.CurrentScope = loopScope
   283→
   284→	c.checkExpression(forStmt.Iterator)
   285→
   286→	// Check body
   287→	for _, stmt := range forStmt.Body {
   288→		c.checkStatement(stmt)
   289→	}
   290→
   291→	c.CurrentScope = prevScope
   292→}
