   294→func (c *Checker) checkForRangeStatement(forStmt *ast.ForRangeStatement) {
   295→	// Check start and end are numeric
   296→	startType := c.checkExpression(forStmt.Start)
   297→	endType := c.checkExpression(forStmt.End)
   298→
   299→	isNumeric := func(t Type) bool {
   300→		if p, ok := t.(*PrimitiveType); ok {
   301→			return p.Name == "i64" || p.Name == "f64"
   302→		}
   303→		return false
   304→	}
   305→
   306→	if !isNumeric(startType) {
   307→		c.addError(0, 0, fmt.Sprintf("range start must be numeric, got %s", startType.TypeString()))
   308→	}
   309→	if !isNumeric(endType) {
   310→		c.addError(0, 0, fmt.Sprintf("range end must be numeric, got %s", endType.TypeString()))
   311→	}
   312→
   313→	// Add loop variable to scope
   314→	loopScope := NewScope(c.CurrentScope)
   315→	prevScope := c.CurrentScope
   316→	c.CurrentScope = loopScope
   317→
   318→	loopScope.Define(forStmt.Variable, startType, "var")
   319→
   320→	// Check body
   321→	for _, stmt := range forStmt.Body {
   322→		c.checkStatement(stmt)
   323→	}
   324→
   325→	c.CurrentScope = prevScope
   326→}
