   334→func (c *Checker) checkMatchStatement(match *ast.MatchStatement) {
   335→	_ = c.checkExpression(match.Expression)
   336→
   337→	for _, arm := range match.Arms {
   338→		for _, stmt := range arm.Body {
   339→			c.checkStatement(stmt)
   340→		}
   341→	}
   342→}
