   344→func (c *Checker) checkBlockStatement(block *ast.BlockStatement) {
   345→	blockScope := NewScope(c.CurrentScope)
   346→	prevScope := c.CurrentScope
   347→	c.CurrentScope = blockScope
   348→
   349→	for _, stmt := range block.Statements {
   350→		c.checkStatement(stmt)
   351→	}
