   356→func (c *Checker) checkExpression(expr ast.Expression) Type {
   357→	switch e := expr.(type) {
   358→	case *ast.IntegerLiteral:
   359→		return &PrimitiveType{Name: "i64"}
   360→	case *ast.FloatLiteral:
   361→		return &PrimitiveType{Name: "f64"}
   362→	case *ast.StringLiteral:
   363→		return &PrimitiveType{Name: "string"}
   364→	case *ast.BoolLiteral:
   365→		return &PrimitiveType{Name: "bool"}
   366→	case *ast.NoneLiteral:
   367→		return &PrimitiveType{Name: "none"}
   368→	case *ast.Identifier:
   369→		return c.checkIdentifier(e)
   370→	case *ast.BinaryExpression:
   371→		return c.checkBinaryExpression(e)
   372→	case *ast.UnaryExpression:
   373→		return c.checkUnaryExpression(e)
   374→	case *ast.CallExpression:
   375→		return c.checkCallExpression(e)
   376→	case *ast.ArrayExpression:
   377→		return c.checkArrayExpression(e)
   378→	case *ast.FieldExpression:
   379→		return c.checkFieldExpression(e)
   380→	case *ast.IndexExpression:
   381→		return c.checkIndexExpression(e)
   382→	case *ast.IfExpression:
   383→		return c.checkIfExpression(e)
   384→	case *ast.MatchExpression:
   385→		return c.checkMatchExpression(e)
   386→	}
   387→	return &PrimitiveType{Name: "none"}
   388→}
