   390→func (c *Checker) checkIdentifier(ident *ast.Identifier) Type {
   391→	sym := c.CurrentScope.Lookup(ident.Name)
   392→	if sym == nil {
   393→		c.addError(0, 0, fmt.Sprintf("undefined variable: %s", ident.Name))
   394→		return &PrimitiveType{Name: "unknown"}
   395→	}
   396→	return sym.Type
   397→}
