   399→func (c *Checker) checkBinaryExpression(bin *ast.BinaryExpression) Type {
   400→	leftType := c.checkExpression(bin.Left)
   401→	rightType := c.checkExpression(bin.Right)
   402→
   403→	// Type-check operator
   404→	return c.inferBinaryOpType(leftType, rightType, bin.Operator)
   405→}
   406→
   407→func (c *Checker) inferBinaryOpType(left, right Type, op string) Type {
   408→	// Arithmetic operators
   409→	if op == "+" || op == "-" || op == "*" || op == "/" || op == "%" {
   410→		if !c.isNumeric(left) || !c.isNumeric(right) {
   411→			c.addError(0, 0, fmt.Sprintf("arithmetic operator %s requires numeric types", op))
   412→			return left
   413→		}
   414→		if !left.Equal(right) {
   415→			c.addError(0, 0, fmt.Sprintf("type mismatch: %s vs %s", left.TypeString(), right.TypeString()))
   416→		}
   417→		return left
   418→	}
   419→
   420→	// Comparison operators
   421→	if op == "==" || op == "!=" || op == "<" || op == ">" || op == "<=" || op == ">=" {
   422→		return &PrimitiveType{Name: "bool"}
   423→	}
   424→
   425→	// Logical operators
   426→	if op == "&&" || op == "||" {
   427→		if !left.Equal(&PrimitiveType{Name: "bool"}) {
   428→			c.addError(0, 0, "logical operator requires bool")
   429→		}
   430→		return &PrimitiveType{Name: "bool"}
   431→	}
   432→
   433→	return left
   434→}
   435→
   436→func (c *Checker) isNumeric(t Type) bool {
   437→	if p, ok := t.(*PrimitiveType); ok {
   438→		return p.Name == "i64" || p.Name == "f64"
   439→	}
   440→	return false
   441→}
   442→
   443→func (c *Checker) checkUnaryExpression(unary *ast.UnaryExpression) Type {
   444→	exprType := c.checkExpression(unary.Operand)
   445→
   446→	if unary.Operator == "-" {
   447→		if !c.isNumeric(exprType) {
   448→			c.addError(0, 0, "unary minus requires numeric type")
   449→		}
   450→		return exprType
   451→	}
   452→
   453→	if unary.Operator == "!" {
   454→		if !exprType.Equal(&PrimitiveType{Name: "bool"}) {
   455→			c.addError(0, 0, "logical not requires bool")
   456→		}
   457→		return &PrimitiveType{Name: "bool"}
   458→	}
   459→
   460→	return exprType
   461→}
   462→
   463→func (c *Checker) checkCallExpression(call *ast.CallExpression) Type {
   464→	fnType := c.checkExpression(call.Function)
   465→
   466→	if ft, ok := fnType.(*FunctionType); ok {
   467→		// Check argument count
   468→		if len(call.Arguments) != len(ft.ParamTypes) {
   469→			c.addError(0, 0, fmt.Sprintf(
   470→				"function expects %d arguments, got %d",
   471→				len(ft.ParamTypes), len(call.Arguments),
   472→			))
   473→		}
   474→
   475→		// Check argument types
   476→		for i, arg := range call.Arguments {
   477→			if i < len(ft.ParamTypes) {
   478→				argType := c.checkExpression(arg)
   479→				expectedType := ft.ParamTypes[i]
   480→				if !argType.Equal(expectedType) {
   481→					c.addError(0, 0, fmt.Sprintf(
   482→						"argument %d: expected %s, got %s",
   483→						i, expectedType.TypeString(), argType.TypeString(),
   484→					))
   485→				}
   486→			}
   487→		}
   488→
   489→		return ft.ReturnType
   490→	}
   491→
   492→	// Handle built-in functions
   493→	if bt, ok := fnType.(*BuiltinFunctionType); ok {
   494→		// Built-in functions like println, print accept any arguments
   495→		if bt.IsVariadic {
   496→			// Just check that arguments are valid expressions
   497→			for _, arg := range call.Arguments {
   498→				c.checkExpression(arg)
   499→			}
   500→			return &PrimitiveType{Name: "none"}
   501→		}
   502→		return &PrimitiveType{Name: "none"}
   503→	}
   504→
   505→	c.addError(0, 0, "cannot call non-function")
   506→	return &PrimitiveType{Name: "none"}
   507→}
   508→
   509→func (c *Checker) checkArrayExpression(arr *ast.ArrayExpression) Type {
   510→	if len(arr.Elements) == 0 {
   511→		// Empty array - type is ambiguous
   512→		return &ArrayType{ElementType: &PrimitiveType{Name: "unknown"}}
   513→	}
   514→
   515→	firstType := c.checkExpression(arr.Elements[0])
   516→
   517→	// Check all elements have same type
   518→	for i := 1; i < len(arr.Elements); i++ {
   519→		elemType := c.checkExpression(arr.Elements[i])
   520→		if !elemType.Equal(firstType) {
   521→			c.addError(0, 0, fmt.Sprintf(
   522→				"array element %d: expected %s, got %s",
   523→				i, firstType.TypeString(), elemType.TypeString(),
   524→			))
   525→		}
   526→	}
   527→
   528→	return &ArrayType{ElementType: firstType}
   529→}
   530→
   531→func (c *Checker) checkFieldExpression(field *ast.FieldExpression) Type {
   532→	exprType := c.checkExpression(field.Object)
   533→
   534→	if st, ok := exprType.(*StructType); ok {
   535→		if fieldType, ok := st.Fields[field.Field]; ok {
   536→			return fieldType
   537→		}
   538→		c.addError(0, 0, fmt.Sprintf("struct %s has no field %s", st.Name, field.Field))
   539→		return &PrimitiveType{Name: "unknown"}
   540→	}
   541→
   542→	c.addError(0, 0, fmt.Sprintf("cannot access field on %s", exprType.TypeString()))
   543→	return &PrimitiveType{Name: "none"}
   544→}
   545→
   546→func (c *Checker) checkIndexExpression(index *ast.IndexExpression) Type {
   547→	exprType := c.checkExpression(index.Object)
   548→	indexType := c.checkExpression(index.Index)
   549→
   550→	// Index must be numeric
   551→	if !c.isNumeric(indexType) {
   552→		c.addError(0, 0, "array index must be numeric")
   553→	}
   554→
   555→	if at, ok := exprType.(*ArrayType); ok {
   556→		return at.ElementType
   557→	}
   558→
   559→	c.addError(0, 0, fmt.Sprintf("cannot index %s", exprType.TypeString()))
   560→	return &PrimitiveType{Name: "none"}
   561→}
   562→
   563→func (c *Checker) checkIfExpression(ifExpr *ast.IfExpression) Type {
   564→	condType := c.checkExpression(ifExpr.Condition)
   565→
   566→	if !condType.Equal(&PrimitiveType{Name: "bool"}) {
   567→		c.addError(0, 0, "if condition must be bool")
   568→	}
   569→
   570→	thenType := c.checkExpression(ifExpr.ThenExpr)
   571→
   572→	if ifExpr.ElseExpr != nil {
   573→		elseType := c.checkExpression(ifExpr.ElseExpr)
   574→		if !thenType.Equal(elseType) {
   575→			c.addError(0, 0, fmt.Sprintf(
   576→				"if/else branch types mismatch: %s vs %s",
   577→				thenType.TypeString(), elseType.TypeString(),
   578→			))
   579→		}
   580→		return thenType
   581→	}
   582→
   583→	return thenType
   584→}
   585→
   586→func (c *Checker) checkMatchExpression(match *ast.MatchExpression) Type {
   587→	_ = c.checkExpression(match.Expression)
   588→
   589→	if len(match.Arms) == 0 {
   590→		return &PrimitiveType{Name: "none"}
   591→	}
   592→
   593→	var firstType Type
   594→	for i, arm := range match.Arms {
   595→		armType := c.checkExpression(arm.Value)
   596→		if i == 0 {
   597→			firstType = armType
   598→		} else if !armType.Equal(firstType) {
   599→			c.addError(0, 0, fmt.Sprintf(
   600→				"match arm %d: expected %s, got %s",
   601→				i, firstType.TypeString(), armType.TypeString(),
   602→			))
   603→		}
   604→	}
   605→
   606→	if firstType == nil {
   607→		return &PrimitiveType{Name: "none"}
   608→	}
   609→	return firstType
   610→}
   611→
   612→func (c *Checker) astTypeToCheckerType(t *ast.Type) Type {
   613→	if t == nil {
   614→		return &PrimitiveType{Name: "none"}
   615→	}
   616→
   617→	if t.IsArray {
   618→		return &ArrayType{ElementType: c.astTypeToCheckerType(t.ElementType)}
   619→	}
   620→
   621→	return &PrimitiveType{Name: t.Name}
   622→}
   623→
   624→func (c *Checker) addError(line, column int, msg string) {
   625→	c.Errors = append(c.Errors, Error{
   626→		Line:    line,
   627→		Column:  column,
   628→		Message: msg,
   629→	})
   630→}
   631→

