     1→// Package typechecker implements type checking and inference for FV 2.0
     2→package typechecker
     3→
     4→import "fmt"
     5→
     6→// Type represents a type in FV 2.0
     7→type Type interface {
     8→	TypeString() string
     9→	Equal(other Type) bool
    10→}
    11→
    12→// PrimitiveType represents built-in types
    13→type PrimitiveType struct {
    14→	Name string // i64, f64, string, bool, none
    15→}
    16→
    17→func (p *PrimitiveType) TypeString() string { return p.Name }
    18→func (p *PrimitiveType) Equal(other Type) bool {
    19→	if o, ok := other.(*PrimitiveType); ok {
    20→		return p.Name == o.Name
    21→	}
    22→	return false
    23→}
    24→
    25→// ArrayType represents an array type
    26→type ArrayType struct {
    27→	ElementType Type
    28→}
    29→
    30→func (a *ArrayType) TypeString() string {
    31→	return "[" + a.ElementType.TypeString() + "]"
    32→}
    33→func (a *ArrayType) Equal(other Type) bool {
    34→	if o, ok := other.(*ArrayType); ok {
    35→		return a.ElementType.Equal(o.ElementType)
    36→	}
    37→	return false
    38→}
    39→
    40→// FunctionType represents a function type
    41→type FunctionType struct {
    42→	ParamTypes []Type
    43→	ReturnType Type
    44→}
    45→
    46→func (f *FunctionType) TypeString() string {
    47→	params := ""
    48→	for i, p := range f.ParamTypes {
    49→		if i > 0 {
    50→			params += ", "
    51→		}
    52→		params += p.TypeString()
    53→	}
    54→	return fmt.Sprintf("fn(%s) %s", params, f.ReturnType.TypeString())
    55→}
    56→func (f *FunctionType) Equal(other Type) bool {
    57→	if o, ok := other.(*FunctionType); ok {
    58→		if len(f.ParamTypes) != len(o.ParamTypes) {
    59→			return false
    60→		}
    61→		for i, p := range f.ParamTypes {
    62→			if !p.Equal(o.ParamTypes[i]) {
    63→				return false
    64→			}
    65→		}
    66→		return f.ReturnType.Equal(o.ReturnType)
    67→	}
    68→	return false
    69→}
    70→
    71→// BuiltinFunctionType represents a built-in function (variadic or special)
    72→type BuiltinFunctionType struct {
    73→	Name       string
    74→	IsVariadic bool
    75→}
    76→
    77→func (b *BuiltinFunctionType) TypeString() string {
    78→	return fmt.Sprintf("builtin(%s)", b.Name)
    79→}
    80→func (b *BuiltinFunctionType) Equal(other Type) bool {
    81→	if o, ok := other.(*BuiltinFunctionType); ok {
    82→		return b.Name == o.Name
    83→	}
    84→	return false
    85→}
    86→
    87→// OptionType represents Option[T]
    88→type OptionType struct {
    89→	InnerType Type
    90→}
    91→
    92→func (o *OptionType) TypeString() string {
    93→	return "Option[" + o.InnerType.TypeString() + "]"
    94→}
    95→func (o *OptionType) Equal(other Type) bool {
    96→	if oo, ok := other.(*OptionType); ok {
    97→		return o.InnerType.Equal(oo.InnerType)
    98→	}
    99→	return false
   100→}
   101→
   102→// ResultType represents Result[T, E]
   103→type ResultType struct {
   104→	OkType    Type
   105→	ErrorType Type
   106→}
   107→
   108→func (r *ResultType) TypeString() string {
   109→	return fmt.Sprintf("Result[%s, %s]", r.OkType.TypeString(), r.ErrorType.TypeString())
   110→}
   111→func (r *ResultType) Equal(other Type) bool {
   112→	if ro, ok := other.(*ResultType); ok {
   113→		return r.OkType.Equal(ro.OkType) && r.ErrorType.Equal(ro.ErrorType)
   114→	}
   115→	return false
   116→}
   117→
   118→// StructType represents a struct type
   119→type StructType struct {
   120→	Name   string
   121→	Fields map[string]Type
   122→}
   123→
   124→func (s *StructType) TypeString() string {
   125→	return "struct " + s.Name
   126→}
   127→func (s *StructType) Equal(other Type) bool {
   128→	if o, ok := other.(*StructType); ok {
   129→		return s.Name == o.Name
   130→	}
   131→	return false
   132→}
   133→
   134→// UnionType represents a union type (e.g., int | string)
   135→type UnionType struct {
   136→	Types []Type
   137→}
   138→
   139→func (u *UnionType) TypeString() string {
   140→	result := ""
   141→	for i, t := range u.Types {
   142→		if i > 0 {
   143→			result += " | "
   144→		}
   145→		result += t.TypeString()
   146→	}
   147→	return result
   148→}
   149→func (u *UnionType) Equal(other Type) bool {
   150→	if o, ok := other.(*UnionType); ok {
   151→		if len(u.Types) != len(o.Types) {
   152→			return false
   153→		}
   154→		for i, t := range u.Types {
   155→			if !t.Equal(o.Types[i]) {
   156→				return false
   157→			}
   158→		}
   159→		return true
   160→	}
   161→	return false
   162→}
   163→
   164→// Symbol represents a variable or function binding
   165→type Symbol struct {
   166→	Name string
   167→	Type Type
   168→	Kind string // "var", "function", "const", "type"
   169→}
   170→
   171→// Scope represents a scope level
   172→type Scope struct {
   173→	Symbols map[string]*Symbol
   174→	Parent  *Scope
   175→}
   176→
   177→// NewScope creates a new scope
   178→func NewScope(parent *Scope) *Scope {
   179→	return &Scope{
   180→		Symbols: make(map[string]*Symbol),
   181→		Parent:  parent,
   182→	}
   183→}
   184→
   185→// Define adds a symbol to the scope
   186→func (s *Scope) Define(name string, typ Type, kind string) {
   187→	s.Symbols[name] = &Symbol{
   188→		Name: name,
   189→		Type: typ,
   190→		Kind: kind,
   191→	}
   192→}
   193→
   194→// Lookup finds a symbol in this scope or parent scopes
   195→func (s *Scope) Lookup(name string) *Symbol {
   196→	if sym, ok := s.Symbols[name]; ok {
   197→		return sym
   198→	}
   199→	if s.Parent != nil {
   200→		return s.Parent.Lookup(name)
   201→	}
   202→	return nil
   203→}
   204→
   205→// Error represents a type checking error
   206→type Error struct {
   207→	Line    int
   208→	Column  int
   209→	Message string
   210→}
   211→
   212→func (e Error) String() string {
   213→	return fmt.Sprintf("%d:%d: %s", e.Line, e.Column, e.Message)
   214→}
